/**
 * build_identity.h - the game build this dylib's addresses came from
 *
 * GENERATED by tools/gen_build_identity.py -- do not edit by hand.
 * One per store under src/gen/<store>/; CMake puts exactly one on the include
 * path (-DBG3_STORE=steam|gog).
 *
 * Steam and GOG ship the same CFBundleShortVersionString (4.1.1.7398727) as
 * different binaries, with deltas of -0x7880, -0x78b0, -0x8750 and -0x80e0 on
 * different symbols. The version string therefore cannot tell you whether this
 * dylib's addresses fit the game it loaded into. Store and binary UUID can.
 *
 * BG3SE_TARGET_BINARY_UUID may be "", meaning unrecorded: the store check still
 * applies, the UUID check is skipped.
 */

#ifndef BG3SE_BUILD_IDENTITY_H
#define BG3SE_BUILD_IDENTITY_H

/* "steam" or "gog", compared against the store detected at runtime. */
#define BG3SE_TARGET_STORE "steam"

/* CFBundleShortVersionString of the binary the addresses came from. */
#define BG3SE_TARGET_VERSION "4.1.1.7398727"

/* arm64 LC_UUID of that binary, uppercase-hyphenated, or "".
 *
 * Taken from ghidra/offsets/ADDRESS_MIGRATION_7398727.md, which records the
 * UUID of the frozen Steam binary the current addresses were derived from,
 * rather than read off an installed game. Re-confirm against a Steam install
 * with `dwarfdump --uuid "<bundle>/Contents/MacOS/Baldur's Gate 3"`; if it
 * disagrees, trust the binary. */
#define BG3SE_TARGET_BINARY_UUID "0C51CAED-6D60-3DCD-9299-8519C92631B0"

#endif /* BG3SE_BUILD_IDENTITY_H */
